---@alias gcp.searchads360_v23.GoogleAdsSearchads360V23Resources__UserListSizeRangeForDisplayEnum "UNSPECIFIED"|"UNKNOWN"|"LESS_THAN_FIVE_HUNDRED"|"LESS_THAN_ONE_THOUSAND"|"ONE_THOUSAND_TO_TEN_THOUSAND"|"TEN_THOUSAND_TO_FIFTY_THOUSAND"|"FIFTY_THOUSAND_TO_ONE_HUNDRED_THOUSAND"|"ONE_HUNDRED_THOUSAND_TO_THREE_HUNDRED_THOUSAND"|"THREE_HUNDRED_THOUSAND_TO_FIVE_HUNDRED_THOUSAND"|"FIVE_HUNDRED_THOUSAND_TO_ONE_MILLION"|"ONE_MILLION_TO_TWO_MILLION"|"TWO_MILLION_TO_THREE_MILLION"|"THREE_MILLION_TO_FIVE_MILLION"|"FIVE_MILLION_TO_TEN_MILLION"|"TEN_MILLION_TO_TWENTY_MILLION"|"TWENTY_MILLION_TO_THIRTY_MILLION"|"THIRTY_MILLION_TO_FIFTY_MILLION"|"OVER_FIFTY_MILLION"

---@alias gcp.searchads360_v23.GoogleAdsSearchads360V23Resources__UserListSizeRangeForSearchEnum "UNSPECIFIED"|"UNKNOWN"|"LESS_THAN_FIVE_HUNDRED"|"LESS_THAN_ONE_THOUSAND"|"ONE_THOUSAND_TO_TEN_THOUSAND"|"TEN_THOUSAND_TO_FIFTY_THOUSAND"|"FIFTY_THOUSAND_TO_ONE_HUNDRED_THOUSAND"|"ONE_HUNDRED_THOUSAND_TO_THREE_HUNDRED_THOUSAND"|"THREE_HUNDRED_THOUSAND_TO_FIVE_HUNDRED_THOUSAND"|"FIVE_HUNDRED_THOUSAND_TO_ONE_MILLION"|"ONE_MILLION_TO_TWO_MILLION"|"TWO_MILLION_TO_THREE_MILLION"|"THREE_MILLION_TO_FIVE_MILLION"|"FIVE_MILLION_TO_TEN_MILLION"|"TEN_MILLION_TO_TWENTY_MILLION"|"TWENTY_MILLION_TO_THIRTY_MILLION"|"THIRTY_MILLION_TO_FIFTY_MILLION"|"OVER_FIFTY_MILLION"

